    header = lines[3]
    delim = ';' if ';' in header else ','
    tss = []
    rows = []
    for l in lines[4:]:
        if not l.strip():
            continue
        parts = l.split(delim)
        ts = parts[0]
        dt = None
        for fmt in ('%Y-%m-%d %H:%M:%S', '%d.%m.%Y %H:%M:%S'):
