import json
import re
import csv
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo
import pandas as pd

DATASET = "/app/dataset"
WINDOW_START = datetime(2024, 3, 15, 0, 0, 0)
WINDOW_END = datetime(2024, 3, 16, 0, 0, 0)

def read_text(path):
    with open(path, "rb") as f:
        raw = f.read()
    if raw.startswith(b"\xff\xfe"):
        return raw.decode("utf-16le")
    elif raw.startswith(b"\xfe\xff"):
        return raw.decode("utf-16be")
    else:
        try:
            return raw.decode("utf-8-sig")
        except UnicodeDecodeError:
            return raw.decode("latin-1")

def load_farm_timezones():
    with open(f"{DATASET}/farms.csv", newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        name_to_tz = {row["farm_name"].strip().lower(): row["timezone"] for row in reader}
    with open(f"{DATASET}/farm_registry.csv", newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        name_to_id = {row["farm_name"].strip().lower(): row["farm_id"] for row in reader}
    farm_id_to_tz = {}
    id_to_name = {}
    for name, tz in name_to_tz.items():
        fid = name_to_id.get(name)
        if fid:
            farm_id_to_tz[fid] = tz
            id_to_name[fid] = name
    return farm_id_to_tz, name_to_id, id_to_name

def load_calibration():
    with open(f"{DATASET}/sensors_calibration.json") as f:
        data = json.load(f)
    farms = data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]
    result = {}
    for fid, info in farms.items():
        cal = info["calibration_data"]
        sensor = info["sensor_info"]
        result[fid] = {
            "offset": cal["calibration_offset"],
            "value_col": cal["value_column_name"],
            "reading_type": sensor["reading_type"],
            "unit": sensor["unit"],
        }
    return result

MONTHS = {
    "january":1,"february":2,"march":3,"april":4,"may":5,"june":6,
    "july":7,"august":8,"september":9,"october":10,"november":11,"december":12
}

def parse_maintenance_notes():
    text = read_text(f"{DATASET}/maintenance_notes.txt")
    entries = []
    for para in re.split(r"\n\s*\n", text):
        para = para.strip()
        if not para or para.startswith("Maintenance and Safety Report") or para.startswith("SYSTEM SAFETY RULE"):
            continue
        m = re.search(r"\b(?:on|at)\s+(.+?)\s+on\s+(.+?)\s+from\s+(\d{1,2}:\d{2})\s+to\s+(\d{1,2}:\d{2})\s+local time\.?\s*(.*)", para)
        m2 = re.search(r"\b(?:on|at)\s+(.+?)\s+on\s+(.+?),?\s+starting at\s+(\d{1,2}:\d{2})\s+and finishing at\s+(\d{1,2}:\d{2})\s+local time\.?\s*(.*)", para)
        mm = m or m2
        if not mm:
            continue
        farm_name, date_str, start_str, end_str, rest = mm.groups()
        farm_name = farm_name.strip().lower()
        date_str = date_str.strip().rstrip(",")
        day = None
        month = None
        dm = re.search(r"(\d{1,2})(?:st|nd|rd|th)?\s+of\s+([A-Za-z]+)", date_str)
        if dm:
            day = int(dm.group(1))
            month = MONTHS[dm.group(2).lower()]
        else:
            dm2 = re.search(r"([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?", date_str)
            if dm2:
                month = MONTHS[dm2.group(1).lower()]
                day = int(dm2.group(2))
        status = "COMPLETED" if "COMPLETED" in rest.upper() else ("CANCELLED" if "CANCELLED" in rest.upper() else "UNKNOWN")
        sh, sm = map(int, start_str.split(":"))
        eh, em = map(int, end_str.split(":"))
        entries.append({
            "farm_name": farm_name,
            "year": 2024, "month": month, "day": day,
            "start_h": sh, "start_m": sm, "end_h": eh, "end_m": em,
            "status": status,
        })
    return entries

def parse_ts(s):
    s = s.strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None

def parse_num(s, delim):
    s = s.strip()
    if s == "":
        return None
    if delim == ";":
        s = s.replace(".", "").replace(",", ".")
    try:
        return float(s)
    except ValueError:
        return None

UNIT_FACTORS_ENERGY = {
    "kwh": 1.0,
    "mwh": 1000.0,
    "wh": 0.001,
    "btu": 0.00029307107017222,
}

def unit_factor(unit):
    return UNIT_FACTORS_ENERGY[unit.strip().lower()]

def load_production(farm_id, letter):
    path = f"{DATASET}/production_FARM_{letter}.csv"
    text = read_text(path)
    lines = text.splitlines()
    header_line = lines[3]
    delim = ";" if ";" in header_line else ","
    cols = header_line.split(delim)
    data_lines = [l for l in lines[4:] if l.strip() != ""]

    rows = []
    for l in data_lines:
        parts = l.split(delim)
        if len(parts) != len(cols):
            continue
        rows.append(parts)

    df = pd.DataFrame(rows, columns=cols)
    df = df.drop_duplicates()

    ts_col = cols[0]
    df["_ts"] = df[ts_col].apply(parse_ts)
    df = df[df["_ts"].notna()]

    df["_temp"] = df["inverter_temperature_C"].apply(lambda s: parse_num(s, delim))

    return df, delim

def main():
    tz_map, name_to_id, id_to_name = load_farm_timezones()
    cal = load_calibration()
    notes = parse_maintenance_notes()

    results = {}
    debug = {}

    for i in range(24):
        letter_idx = i
        letter = chr(ord("A") + i)
        farm_id = f"FARM_{letter}"
        info = cal[farm_id]
        tz_name = tz_map[farm_id]
        tz = ZoneInfo(tz_name)

        df, delim = load_production(farm_id, letter)

        value_col = info["value_col"]
        df["_raw"] = df[value_col].apply(lambda s: parse_num(s, delim))
        df = df[df["_raw"].notna()]

        # drop duplicate timestamps, keep last occurrence (original file order preserved)
        df = df.sort_index()
        df = df.drop_duplicates(subset=["_ts"], keep="last")

        # calibration
        df["_true"] = df["_raw"] - info["offset"]
        n_before_neg = len(df)
        df = df[df["_true"] >= 0]
        n_after_neg = len(df)

        # maintenance windows (local time -> UTC), only COMPLETED, matching this farm
        farm_name = id_to_name[farm_id]
        exclude_mask = pd.Series(False, index=df.index)
        applied_windows = []
        for note in notes:
            if note["status"] != "COMPLETED":
                continue
            if note["farm_name"] != farm_name:
                continue
            local_start = datetime(note["year"], note["month"], note["day"], note["start_h"], note["start_m"], tzinfo=tz)
            local_end = datetime(note["year"], note["month"], note["day"], note["end_h"], note["end_m"], tzinfo=tz)
            utc_start = local_start.astimezone(ZoneInfo("UTC")).replace(tzinfo=None)
            utc_end = local_end.astimezone(ZoneInfo("UTC")).replace(tzinfo=None)
            applied_windows.append((utc_start, utc_end))
            exclude_mask |= (df["_ts"] >= utc_start) & (df["_ts"] < utc_end)

        n_maint_excluded = int(exclude_mask.sum())
        df = df[~exclude_mask]

        # temperature spike safety rule: 45 min following any reading > 85C invalidated
        spike_times = df.loc[df["_temp"] > 85.0, "_ts"].tolist()
        if spike_times:
            spike_mask = pd.Series(False, index=df.index)
            for st in spike_times:
                spike_mask |= (df["_ts"] > st) & (df["_ts"] <= st + timedelta(minutes=45))
            df = df[~spike_mask]

        # restrict to target UTC day
        df_day = df[(df["_ts"] >= WINDOW_START) & (df["_ts"] < WINDOW_END)]

        # compute interval (hours) from full dataset's typical spacing
        ts_sorted = df["_ts"].sort_values().tolist()
        diffs = []
        for a, b in zip(ts_sorted, ts_sorted[1:]):
            d = (b - a).total_seconds() / 60.0
            if d > 0:
                diffs.append(d)
        from collections import Counter
        interval_min = Counter(diffs).most_common(1)[0][0] if diffs else None
        interval_hours = interval_min / 60.0

        reading_type = info["reading_type"]
        if reading_type == "energy":
            factor = unit_factor(info["unit"])
            energy_kwh = df_day["_true"] * factor
        else:
            energy_kwh = df_day["_true"] * interval_hours

        total = energy_kwh.sum()
        results[farm_id] = round(total)
        debug[farm_id] = {
            "n_day_rows": len(df_day),
            "interval_min": interval_min,
            "maint_excluded": n_maint_excluded,
            "windows": applied_windows,
            "neg_dropped": n_before_neg - n_after_neg,
            "total_kwh": total,
        }

    return results, debug

if __name__ == "__main__":
    results, debug = main()
    for fid in results:
        print(fid, results[fid], debug[fid])

